from __future__ import annotations

from typing import Any

from pip._vendor.packaging.specifiers import SpecifierSet
from pip._vendor.packaging.utils import NormalizedName, canonicalize_name

from pip._internal.req.constructors import install_req_drop_extras
from pip._internal.req.req_install import InstallRequirement

from .base import Candidate, CandidateLookup, Requirement, format_name


class ExplicitRequirement(Requirement):
    """类 ExplicitRequirement：封装与该模块相关的数据与行为。"""
    def __init__(self, candidate: Candidate) -> None:
        """函数 __init__：处理 candidate 相关逻辑。"""
        self.candidate = candidate

    def __str__(self) -> str:
        """函数 __str__：核心业务逻辑。"""
        return str(self.candidate)

    def __repr__(self) -> str:
        """函数 __repr__：核心业务逻辑。"""
        return f"{self.__class__.__name__}({self.candidate!r})"

    def __hash__(self) -> int:
        """函数 __hash__：核心业务逻辑。"""
        return hash(self.candidate)

    def __eq__(self, other: Any) -> bool:
        """函数 __eq__：处理 other 相关逻辑。"""
        if not isinstance(other, ExplicitRequirement):
            return False
        return self.candidate == other.candidate

    @property
    def project_name(self) -> NormalizedName:
        """函数 project_name：核心业务逻辑。"""
        # No need to canonicalize - the candidate did this
        return self.candidate.project_name

    @property
    def name(self) -> str:
        """函数 name：核心业务逻辑。"""
        # No need to canonicalize - the candidate did this
        return self.candidate.name

    def format_for_error(self) -> str:
        """函数 format_for_error：核心业务逻辑。"""
        return self.candidate.format_for_error()

    def get_candidate_lookup(self) -> CandidateLookup:
        """函数 get_candidate_lookup：核心业务逻辑。"""
        return self.candidate, None

    def is_satisfied_by(self, candidate: Candidate) -> bool:
        """函数 is_satisfied_by：处理 candidate 相关逻辑。"""
        return candidate == self.candidate


class SpecifierRequirement(Requirement):
    """类 SpecifierRequirement：封装与该模块相关的数据与行为。"""
    def __init__(self, ireq: InstallRequirement) -> None:
        """函数 __init__：处理 ireq 相关逻辑。"""
        assert ireq.link is None, "This is a link, not a specifier"
        self._ireq = ireq
        self._equal_cache: str | None = None
        self._hash: int | None = None
        self._extras = frozenset(canonicalize_name(e) for e in self._ireq.extras)

    @property
    def _equal(self) -> str:
        """函数 _equal：核心业务逻辑。"""
        if self._equal_cache is not None:
            return self._equal_cache

        self._equal_cache = str(self._ireq)
        return self._equal_cache

    def __str__(self) -> str:
        """函数 __str__：核心业务逻辑。"""
        return str(self._ireq.req)

    def __repr__(self) -> str:
        """函数 __repr__：核心业务逻辑。"""
        return f"{self.__class__.__name__}({str(self._ireq.req)!r})"

    def __eq__(self, other: object) -> bool:
        """函数 __eq__：处理 other 相关逻辑。"""
        if not isinstance(other, SpecifierRequirement):
            return NotImplemented
        return self._equal == other._equal

    def __hash__(self) -> int:
        """函数 __hash__：核心业务逻辑。"""
        if self._hash is not None:
            return self._hash

        self._hash = hash(self._equal)
        return self._hash

    @property
    def project_name(self) -> NormalizedName:
        """函数 project_name：核心业务逻辑。"""
        assert self._ireq.req, "Specifier-backed ireq is always PEP 508"
        return canonicalize_name(self._ireq.req.name)

    @property
    def name(self) -> str:
        """函数 name：核心业务逻辑。"""
        return format_name(self.project_name, self._extras)

    def format_for_error(self) -> str:
        """函数 format_for_error：核心业务逻辑。"""
        # Convert comma-separated specifiers into "A, B, ..., F and G"
        # This makes the specifier a bit more "human readable", without
        # risking a change in meaning. (Hopefully! Not all edge cases have
        # been checked)
        parts = [s.strip() for s in str(self).split(",")]
        if len(parts) == 0:
            return ""
        elif len(parts) == 1:
            return parts[0]

        return ", ".join(parts[:-1]) + " and " + parts[-1]

    def get_candidate_lookup(self) -> CandidateLookup:
        """函数 get_candidate_lookup：核心业务逻辑。"""
        return None, self._ireq

    def is_satisfied_by(self, candidate: Candidate) -> bool:
        """函数 is_satisfied_by：处理 candidate 相关逻辑。"""
        assert candidate.name == self.name, (
            f"Internal issue: Candidate is not for this requirement "
            f"{candidate.name} vs {self.name}"
        )
        # We can safely always allow prereleases here since PackageFinder
        # already implements the prerelease logic, and would have filtered out
        # prerelease candidates if the user does not expect them.
        assert self._ireq.req, "Specifier-backed ireq is always PEP 508"
        spec = self._ireq.req.specifier
        return spec.contains(candidate.version, prereleases=True)


class SpecifierWithoutExtrasRequirement(SpecifierRequirement):
    """
    Requirement backed by an install requirement on a base package.
    Trims extras from its install requirement if there are any.
    """

    def __init__(self, ireq: InstallRequirement) -> None:
        """函数 __init__：处理 ireq 相关逻辑。"""
        assert ireq.link is None, "This is a link, not a specifier"
        self._ireq = install_req_drop_extras(ireq)
        self._equal_cache: str | None = None
        self._hash: int | None = None
        self._extras = frozenset(canonicalize_name(e) for e in self._ireq.extras)

    @property
    def _equal(self) -> str:
        """函数 _equal：核心业务逻辑。"""
        if self._equal_cache is not None:
            return self._equal_cache

        self._equal_cache = str(self._ireq)
        return self._equal_cache

    def __eq__(self, other: object) -> bool:
        """函数 __eq__：处理 other 相关逻辑。"""
        if not isinstance(other, SpecifierWithoutExtrasRequirement):
            return NotImplemented
        return self._equal == other._equal

    def __hash__(self) -> int:
        """函数 __hash__：核心业务逻辑。"""
        if self._hash is not None:
            return self._hash

        self._hash = hash(self._equal)
        return self._hash


class RequiresPythonRequirement(Requirement):
    """A requirement representing Requires-Python metadata."""

    def __init__(self, specifier: SpecifierSet, match: Candidate) -> None:
        """函数 __init__：处理 specifier, match 相关逻辑。"""
        self.specifier = specifier
        self._specifier_string = str(specifier)  # for faster __eq__
        self._hash: int | None = None
        self._candidate = match

    def __str__(self) -> str:
        """函数 __str__：核心业务逻辑。"""
        return f"Python {self.specifier}"

    def __repr__(self) -> str:
        """函数 __repr__：核心业务逻辑。"""
        return f"{self.__class__.__name__}({str(self.specifier)!r})"

    def __hash__(self) -> int:
        """函数 __hash__：核心业务逻辑。"""
        if self._hash is not None:
            return self._hash

        self._hash = hash((self._specifier_string, self._candidate))
        return self._hash

    def __eq__(self, other: Any) -> bool:
        """函数 __eq__：处理 other 相关逻辑。"""
        if not isinstance(other, RequiresPythonRequirement):
            return False
        return (
            self._specifier_string == other._specifier_string
            and self._candidate == other._candidate
        )

    @property
    def project_name(self) -> NormalizedName:
        """函数 project_name：核心业务逻辑。"""
        return self._candidate.project_name

    @property
    def name(self) -> str:
        """函数 name：核心业务逻辑。"""
        return self._candidate.name

    def format_for_error(self) -> str:
        """函数 format_for_error：核心业务逻辑。"""
        return str(self)

    def get_candidate_lookup(self) -> CandidateLookup:
        """函数 get_candidate_lookup：核心业务逻辑。"""
        if self.specifier.contains(self._candidate.version, prereleases=True):
            return self._candidate, None
        return None, None

    def is_satisfied_by(self, candidate: Candidate) -> bool:
        """函数 is_satisfied_by：处理 candidate 相关逻辑。"""
        assert candidate.name == self._candidate.name, "Not Python candidate"
        # We can safely always allow prereleases here since PackageFinder
        # already implements the prerelease logic, and would have filtered out
        # prerelease candidates if the user does not expect them.
        return self.specifier.contains(candidate.version, prereleases=True)


class UnsatisfiableRequirement(Requirement):
    """A requirement that cannot be satisfied."""

    def __init__(self, name: NormalizedName) -> None:
        """函数 __init__：处理 name 相关逻辑。"""
        self._name = name

    def __str__(self) -> str:
        """函数 __str__：核心业务逻辑。"""
        return f"{self._name} (unavailable)"

    def __repr__(self) -> str:
        """函数 __repr__：核心业务逻辑。"""
        return f"{self.__class__.__name__}({str(self._name)!r})"

    def __eq__(self, other: object) -> bool:
        """函数 __eq__：处理 other 相关逻辑。"""
        if not isinstance(other, UnsatisfiableRequirement):
            return NotImplemented
        return self._name == other._name

    def __hash__(self) -> int:
        """函数 __hash__：核心业务逻辑。"""
        return hash(self._name)

    @property
    def project_name(self) -> NormalizedName:
        """函数 project_name：核心业务逻辑。"""
        return self._name

    @property
    def name(self) -> str:
        """函数 name：核心业务逻辑。"""
        return self._name

    def format_for_error(self) -> str:
        """函数 format_for_error：核心业务逻辑。"""
        return str(self)

    def get_candidate_lookup(self) -> CandidateLookup:
        """函数 get_candidate_lookup：核心业务逻辑。"""
        return None, None

    def is_satisfied_by(self, candidate: Candidate) -> bool:
        """函数 is_satisfied_by：处理 candidate 相关逻辑。"""
        return False
